import{_ as l,l as i,o as e,c as d,v as r,p as n,x as o,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"过程间分析与调用图","description":"","frontmatter":{"title":"过程间分析与调用图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interprocedural-callgraph.md","filePath":"cs/interprocedural-callgraph.md","lastUpdated":1789023840000}'),h={name:"cs/interprocedural-callgraph.md"};function C(_,a,m,E,u,f){const t=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="过程间分析与调用图" tabindex="-1">过程间分析与调用图 <a class="header-anchor" href="#过程间分析与调用图" aria-label="Permalink to &quot;过程间分析与调用图&quot;">​</a></h1><div class="epigraph"><p>过程内分析在调用处停下。调用图给出谁调用谁；过程间分析沿边传摘要或内联式克隆。间接调用靠指向分析补边。</p><footer>—— 据 Callahan, Cooper 等过程间分析；Grove and Chambers 调用图；龙书 12 章整理</footer></div><p>上一课<a href="/cs/points-to-analysis">指向分析</a>在过程内给 <code>*p</code>。缺口是<strong>跨函数</strong>：<code>foo</code> 写不清全局，<code>bar</code> 的 load 就不能 LICM。调用图（CG）：节点函数，边调用点。间接：函数指针、虚调用。本课钉 CHA/指向建图与摘要，不写完整内联启发——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无 CG 则每个调用当「什么都写」。精确 CG 依赖指向，指向依赖 CG，迭代。CHA（类层次）：虚调用接到所有覆写，保守。缺口是<strong>图 + 摘要</strong>（mod/ref 集合），不是 Andersen 约束细节。</p><p>上下文敏感：同一函数因调用点不同有不同摘要，减污染，占内存。</p><h3 id="调用图不是-cfg" tabindex="-1">调用图不是 CFG <a class="header-anchor" href="#调用图不是-cfg" aria-label="Permalink to &quot;调用图不是 CFG&quot;">​</a></h3><p>CFG 是过程内块；CG 是过程间。不要把 <code>call</code> 指令的 CFG 后继当 CG 的唯一定义——间接边会变。</p><p><span class="marginnote">Grove–Chambers。Horwitz–Reps–Binkley 系统依赖图点名。龙书过程间。本课不写完整 IFDS/IDE 算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先 CHA 或声明分析建粗图。跑指向，加边，直到稳。每函数算 mod/ref、纯否、不抛否。优化查询：调用是否写某对象。</p>',11)),(e(),n(p,null,{default:o(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHA%5B%22%E7%B1%BB%E5%B1%82%E6%AC%A1%20%2F%20%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20CG%5B%22%E8%B0%83%E7%94%A8%E5%9B%BE%22%5D%0A%20%20PT%5B%22%E6%8C%87%E5%90%91%22%5D%20--%3E%20CG%0A%20%20CG%20--%3E%20SUM%5B%22%E8%BF%87%E7%A8%8B%E6%91%98%E8%A6%81%22%5D%0A%20%20SUM%20--%3E%20OPT%5B%22%E8%BF%87%E7%A8%8B%E9%97%B4%E5%B8%B8%E9%87%8F%20%2F%20DCE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 SCCP：IPSCCP 沿 CG 传常量。与 LTO：全程序 CG 更全，后课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归与 SCC：摘要要在强连通分量上迭代。动态加载（<code>dlopen</code>）使 CG 开世界，须保守。不要把 JIT 的运行时 CG 当 AOT 的同一对象，运行时单元再谈。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内联预算。后课默认：优化可问「callee 写什么」。下一课内联启发：用 CG 与体大小决定复制。</p><p>也不把微服务 RPC 当调用图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调用图 + 摘要 = 过程间分析的骨架。</li><li>间接调用与指向联立迭代。</li><li>开世界（动态加载）强制保守。</li><li>出处：Callahan/Cooper；Grove and Chambers；龙书第 12 章。</li></ul>',8))])}const G=l(h,[["render",C]]);export{B as __pageData,G as default};
